const root=()=>document.querySelector('#view');
const current=()=>location.hash.slice(1).split('/')[0]||'home';
const icons={home:'<path d="m3 10 5-5 5 5v5H9v-3H7v3H3z"/>',runs:'<circle cx="8" cy="8" r="5"/><path d="m8 5 2 3-2 2-2-2z"/>',workspaces:'<rect x="3" y="3" width="4" height="4"/><rect x="9" y="3" width="4" height="4"/><rect x="3" y="9" width="4" height="4"/><rect x="9" y="9" width="4" height="4"/>',workflows:'<path d="M3 4h5v4H3zM8 6h5v4H8zM3 10h5v4H3z"/><path d="M8 6h1M8 12h1"/>',sql:'<path d="M3 4h10M3 8h7M3 12h5"/>',catalog:'<path d="M3 3h10v10H3zM6 3v10M3 7h10"/>'};
Object.assign(icons,{quality:'<path d="M8 2 13 4v4c0 3.2-2 5.1-5 6-3-0.9-5-2.8-5-6V4z"/><path d="m5.5 8 1.5 1.5L10.8 6"/>',alerts:'<path d="M8 2.5a3 3 0 0 1 3 3v1.2c0 .8.3 1.5.8 2.1l.7.8H3.5l.7-.8c.5-.6.8-1.3.8-2.1V5.5a3 3 0 0 1 3-3Z"/><path d="M6.6 12.2a1.6 1.6 0 0 0 2.8 0"/>',finops:'<path d="M8 2v12M10.5 4.2C10 3.4 9.1 3 8 3 6.3 3 5 3.9 5 5.1S6.1 7 8 7s3 1 3 2.1S9.7 11 8 11c-1.1 0-2-.4-2.5-1.2"/>',migration:'<circle cx="4" cy="8" r="2"/><circle cx="12" cy="4" r="2"/><circle cx="12" cy="12" r="2"/><path d="m5.7 7 4.6-2M5.7 9l4.6 2"/>',synthetic:'<path d="m8 2 1.2 3.4L12.5 7l-3.3 1.6L8 12l-1.2-3.4L3.5 7l3.3-1.6z"/><path d="m13 10 .5 1.5L15 12l-1.5.5L13 14l-.5-1.5L11 12l1.5-.5z"/>',mlstudio:'<path d="M3 12.5V9M6.3 12.5V6M9.7 12.5V3.5M13 12.5V7"/><path d="M2 13.5h12"/>',data:'<ellipse cx="8" cy="4" rx="5" ry="2"/><path d="M3 4v4c0 1.1 2.2 2 5 2s5-.9 5-2V4M3 8v4c0 1.1 2.2 2 5 2s5-.9 5-2V8"/>',ingestion:'<path d="M8 2v8M5 7l3 3 3-3"/><path d="M3 11v2h10v-2"/>',notebooks:'<path d="M4 2h8a1 1 0 0 1 1 1v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V3a1 1 0 0 1 1-1Z"/><path d="M6 5h4M6 8h4M6 11h2"/>',streaming:'<path d="M2 8h3l1.3-3 2.2 6L10 8h4"/>',graphs:'<circle cx="4" cy="11" r="1.5"/><circle cx="8" cy="4" r="1.5"/><circle cx="12" cy="10" r="1.5"/><path d="m5.2 10 1.6-4.7M9.3 5l1.5 3.8"/>',performance:'<path d="M2.5 12.5h11"/><path d="m3 10 3-3 2 2 4-5"/><path d="M12 4h2v2"/>',debugger:'<path d="M5 3h6v10H5z"/><path d="M3 5h2M3 8h2M3 11h2M11 5h2M11 8h2M11 11h2"/>',cloud:'<path d="M4.5 12.5h7a2 2 0 0 0 .4-4 4 4 0 0 0-7.6-1.2 2.6 2.6 0 0 0 .2 5.2Z"/>',deployments:'<path d="M8 2 13 5v6l-5 3-5-3V5z"/><path d="M5.2 6.2 8 8l2.8-1.8M8 8v3.2"/>',environments:'<path d="M3 3h10v3H3zM3 7h10v3H3zM3 11h10v2H3z"/>',settings:'<path d="M6.7 2h2.6l.4 1.7a4.5 4.5 0 0 1 1.2.7l1.6-.6 1.3 2.2-1.3 1.1a4.7 4.7 0 0 1 0 1.4l1.3 1.1-1.3 2.2-1.6-.6a4.5 4.5 0 0 1-1.2.7L9.3 14H6.7l-.4-1.7a4.5 4.5 0 0 1-1.2-.7l-1.6.6-1.3-2.2 1.3-1.1a4.7 4.7 0 0 1 0-1.4L2.2 6.4l1.3-2.2 1.6.6a4.5 4.5 0 0 1 1.2-.7z"/><circle cx="8" cy="8" r="1.6"/>',projects:'<path d="M2.5 4.5h4l1.2 1.4h5.8v6.6h-11z"/><path d="M2.5 6h11"/>',home:'<path d="m2.5 7.5 5.5-5 5.5 5v5h-4v-3h-3v3h-4z"/>',run:'<circle cx="8" cy="8" r="5"/><path d="m7 5 3 3-3 3z"/>'});function svg(path){return `<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`}
function replaceIcons(){document.querySelectorAll('.nav-item').forEach(item=>{const href=item.getAttribute('href')||'';const key=href.slice(1);const path=icons[key]||'<circle cx="8" cy="8" r="5"/><path d="M8 3v10M3 8h10"/>';item.querySelector('span')?.replaceChildren();item.querySelector('span').innerHTML=svg(path)});const toggle=document.querySelector('[data-action="toggle-sidebar"]');if(toggle){const icon=toggle.querySelector('.rail-toggle-icon');if(icon)icon.innerHTML=svg('<path d="m11 3-5 5 5 5"/><path d="M13 8H3"/>');}const command=document.querySelector('[data-action="open-command"]');if(command)command.innerHTML=svg('<circle cx="7" cy="7" r="4"/><path d="m10 10 3 3"/>');}
function error(message){return `<div class="error"><strong>Request failed</strong><p>${esc(message)}</p></div>`}
function workspaceId(){return document.querySelector('#feature-workspace')?.value.trim()||sessionStorage.getItem('ronin.workspace')||'default'}
async function environments(){root().innerHTML=`${page('Environments','DEPLOYMENT')}<div class="toolbar"><label>Workspace<input class="field" id="environment-workspace" value="${esc(sessionStorage.getItem('ronin.workspace')||'default')}"></label><button class="button primary" data-feature="load-environments">Refresh environments</button></div><form class="panel" data-feature-form="environment-create"><h2>Create environment</h2><div class="toolbar"><input class="field" name="id" placeholder="prod" required><input class="field" name="name" placeholder="Production" required><input class="field" name="description" placeholder="Description"><button class="button primary">Create</button></div></form><div id="environment-result" class="loading">Loading environments…</div>`;loadEnvironments()}
async function loadEnvironments(){const id=document.querySelector('#environment-workspace')?.value.trim()||'default';sessionStorage.setItem('ronin.workspace',id);const out=document.querySelector('#environment-result');try{const data=await get(`/v1/workspaces/${encodeURIComponent(id)}/environments`);const rows=data.items||[];out.className='';out.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Name</th><th>ID</th><th>State</th><th>Actions</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.name)}</td><td><code>${esc(e.id)}</code></td><td>${status(e.state)}</td><td>${e.state==='active'?`<button class="button danger" data-feature="disable-environment" data-environment="${esc(e.id)}">Disable</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No environments are registered.</div>'}catch(e){out.className='';out.innerHTML=error(e.message)}}
async function createEnvironment(form){const d=Object.fromEntries(new FormData(form));const id=document.querySelector('#environment-workspace').value.trim();try{await post(`/v1/workspaces/${encodeURIComponent(id)}/environments`,{id:d.id,name:d.name,description:d.description||'',state:'active'});form.reset();await loadEnvironments()}catch(e){form.insertAdjacentHTML('afterend',error(e.message))}}
async function disableEnvironment(environment){const id=sessionStorage.getItem('ronin.workspace')||'default';if(!await confirmImpact(`Disable environment ${environment}?`))return;try{await post(`/v1/workspaces/${encodeURIComponent(id)}/environments/${encodeURIComponent(environment)}/disable`,{});await loadEnvironments()}catch(e){document.querySelector('#environment-result').innerHTML=error(e.message)}}
async function enableEnvironment(environment){const id=sessionStorage.getItem('ronin.workspace')||'default';try{await post(`/v1/workspaces/${encodeURIComponent(id)}/environments/${encodeURIComponent(environment)}/enable`,{});await loadEnvironments()}catch(e){document.querySelector('#environment-result').innerHTML=error(e.message)}}
async function loadWorkflows(){const id=workspaceId();sessionStorage.setItem('ronin.workspace',id);const out=document.querySelector('#workflow-result');out.className='loading';out.textContent='Loading workflows…';try{const data=await get(`/v1/workspaces/${encodeURIComponent(id)}/workflows`);const rows=data.items||[];out.className='';out.innerHTML=rows.length?`<div class="table-wrap"><table><caption class="sr-only">Published workflows</caption><thead><tr><th>Name</th><th>Workflow</th><th>Actions</th></tr></thead><tbody>${rows.map(w=>`<tr><td><strong>${esc(w.name||w.id)}</strong></td><td><code>${esc(w.id)}</code></td><td><button class="button primary" data-feature="run-workflow" data-workflow="${esc(w.id)}">Run</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No workflows are visible in this workspace.</div>'}catch(e){out.className='';out.innerHTML=error(e.message)}}
async function runWorkflow(workflow){try{const result=await post(`/v1/workspaces/${encodeURIComponent(workspaceId())}/workflows/${encodeURIComponent(workflow)}/runs`,{});await loadWorkflows();if(result.id){document.querySelector('#workflow-run-id').value=result.id;showWorkflowRun(result.id)}}catch(e){document.querySelector('#workflow-result').innerHTML=error(e.message)}}
async function showWorkflowRun(runId){const out=document.querySelector('#workflow-run-result');out.className='loading';out.textContent='Loading workflow run…';try{const data=await get(`/v1/workspaces/${encodeURIComponent(workspaceId())}/workflow-runs/${encodeURIComponent(runId)}`);out.className='panel';out.innerHTML=`<h2>Workflow run ${esc(runId)}</h2><p>${status(data.state||data.status||'unknown')}</p><pre class="code">${esc(json(data))}</pre><button class="button danger" data-feature="cancel-workflow-run" data-run="${esc(runId)}">Cancel run</button>`}catch(e){out.className='';out.innerHTML=error(e.message)}}
async function cancelWorkflowRun(runId){if(!await confirmImpact(`Cancel workflow run ${runId}? Produced evidence is preserved and cancellation cannot be reversed.`))return;try{await post(`/v1/workspaces/${encodeURIComponent(workspaceId())}/workflow-runs/${encodeURIComponent(runId)}/cancel`,{});await showWorkflowRun(runId)}catch(e){document.querySelector('#workflow-run-result').innerHTML=error(e.message)}}
async function workspaces(){root().innerHTML=`${page('Workspaces','FOUNDATION')}<div class="toolbar"><button class="button primary" data-feature="load-workspaces">Refresh workspaces</button><input class="field" id="workspace-id" placeholder="Workspace id" aria-label="Workspace id"><button class="button" data-feature="load-projects">Load projects</button></div><div id="workspace-result" class="loading">Loading workspaces…</div><div id="project-result" class="loading feature-output">Select a workspace to load projects.</div>`;loadWorkspaces()}
async function loadWorkspaces(){const out=document.querySelector('#workspace-result');try{const data=await get('/v1/workspaces');const rows=data.items||[];out.className='';out.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Name</th><th>ID</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(w=>`<tr><td>${esc(w.name||w.id)}</td><td><code>${esc(w.id)}</code></td><td>${status(w.status||'active')}</td><td><button class="button" data-feature="select-workspace" data-workspace="${esc(w.id)}">Select</button><button class="button" data-feature="archive-workspace" data-workspace="${esc(w.id)}">Archive</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No workspaces are visible.</div>'}catch(e){out.className='';out.innerHTML=error(e.message)}}
async function inspectWorkspace(id){try{const data=await get(`/v1/workspaces/${encodeURIComponent(id)}`);document.querySelector('#workspace-result').insertAdjacentHTML('beforeend',`<pre class="code feature-output">${esc(json(data))}</pre>`)}catch(e){document.querySelector('#workspace-result').insertAdjacentHTML('beforeend',error(e.message))}}
async function loadProjects(){const id=document.querySelector('#workspace-id')?.value.trim()||sessionStorage.getItem('ronin.workspace')||'default';sessionStorage.setItem('ronin.workspace',id);const out=document.querySelector('#project-result');out.className='loading';out.textContent='Loading projects…';try{const data=await get(`/v1/workspaces/${encodeURIComponent(id)}/projects`);const rows=data.items||[];out.className='';out.innerHTML=`<div class="panel"><h2>Projects in ${esc(id)}</h2><form data-feature-form="project-create" class="toolbar"><input class="field" name="project_id" placeholder="Project id" required><input class="field" name="name" placeholder="Project name" required><button class="button primary">Register project</button></form>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Project</th><th>Actions</th></tr></thead><tbody>${rows.map(project=>`<tr><td><strong>${esc(project.name||project.id)}</strong><br><code>${esc(project.id)}</code></td><td><button class="button" data-feature="inspect-project" data-project="${esc(project.id)}">Inspect</button><button class="button" data-feature="delete-project" data-project="${esc(project.id)}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No projects are registered.</div>'}</div>`}catch(e){out.className='';out.innerHTML=error(e.message)}}
async function inspectProject(id){const workspace=sessionStorage.getItem('ronin.workspace')||'default';try{const data=await get(`/v1/workspaces/${encodeURIComponent(workspace)}/projects/${encodeURIComponent(id)}`);document.querySelector('#project-result').insertAdjacentHTML('beforeend',`<pre class="code feature-output">${esc(json(data))}</pre>`)}catch(e){document.querySelector('#project-result').insertAdjacentHTML('beforeend',error(e.message))}}
async function submitProject(form){const data=Object.fromEntries(new FormData(form));const id=sessionStorage.getItem('ronin.workspace')||'default';try{await post(`/v1/workspaces/${encodeURIComponent(id)}/projects`,{id:data.project_id,name:data.name});await loadProjects()}catch(e){form.insertAdjacentHTML('afterend',error(e.message))}}
function confirmImpact(message){return new Promise(resolve=>{const dialog=document.querySelector('#confirm-dialog');document.querySelector('#confirm-title').textContent='Confirm impact';document.querySelector('#confirm-copy').textContent=message;const submit=document.querySelector('#confirm-submit');const done=value=>{dialog.close();submit.onclick=null;resolve(value)};submit.onclick=()=>done(true);dialog.addEventListener('close',()=>done(false),{once:true});dialog.showModal()})}
async function archiveWorkspace(id){if(!await confirmImpact(`Archive workspace ${id}? This action is not reversible from the UI.`))return;try{await post(`/v1/workspaces/${encodeURIComponent(id)}/archive`,{});await loadWorkspaces()}catch(e){document.querySelector('#workspace-result').innerHTML=error(e.message)}}
async function deleteProject(id){if(!await confirmImpact(`Delete project ${id}? The project registration will be removed.`))return;const workspace=sessionStorage.getItem('ronin.workspace')||'default';try{await del(`/v1/workspaces/${encodeURIComponent(workspace)}/projects/${encodeURIComponent(id)}`);await loadProjects()}catch(e){document.querySelector('#project-result').innerHTML=error(e.message)}}
function workspaceControls(){document.querySelector('#workspace-result')?.insertAdjacentHTML('afterend',`<div class="grid two feature-output"><form class="panel" data-feature-form="workspace-update"><h2>Update workspace</h2><label>Workspace ID<input class="field" name="id" required></label><label>Name<input class="field" name="name" required></label><label>Description<textarea class="field" name="description"></textarea></label><button class="button primary">Save workspace</button></form><form class="panel" data-feature-form="project-replace"><h2>Replace project manifest</h2><label>Project ID<input class="field" name="project_id" required></label><label>Project name<input class="field" name="name" required></label><button class="button primary">Replace project</button></form></div>`)}
function jobSubmitPanel(){if(document.querySelector('#job-submit-panel'))return;document.querySelector('#view')?.insertAdjacentHTML('beforeend',`<form id="job-submit-panel" class="panel feature-output" data-feature-form="job-submit"><h2>Submit a run</h2><div class="toolbar"><input class="field" name="project" value="examples/demo" placeholder="Project" required><input class="field" name="target" value="notebooks/etl" placeholder="Target" required><button class="button primary">Submit job</button></div></form>`)}
async function submitJob(form){const data=Object.fromEntries(new FormData(form));try{const result=await post('/v1/jobs',{project:data.project,target:data.target,parameters:{}});form.insertAdjacentHTML('afterend',`<div class="empty">Submitted ${esc(result.id||'job')}.</div>`)}catch(e){form.insertAdjacentHTML('afterend',error(e.message))}}
function exportMLCompare(format){if(!mlCompareExport)return;let content;let mediaType;let filename;if(format==='json'){content=JSON.stringify(mlCompareExport,null,2);mediaType='application/json';filename='ml-trial-comparison.json'}else{const quote=value=>`"${String(value).replaceAll('"','""')}"`;const rows=[['rank','trial_id','parameters_json','metrics_json'],...mlCompareExport.items.map((trial,index)=>[index+1,trial.trial_id,JSON.stringify(trial.parameters),JSON.stringify(trial.metrics)])];content=rows.map(row=>row.map(quote).join(',')).join('\r\n');mediaType='text/csv;charset=utf-8';filename='ml-trial-comparison.csv'}const url=URL.createObjectURL(new Blob([content],{type:mediaType}));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function machineLearningStudio(){
  root().innerHTML=`${page('Machine Learning Studio','EXPERIMENTATION')}<div class="toolbar"><label>Workspace<input class="field" id="ml-workspace" value="${esc(sessionStorage.getItem('ronin.workspace')||'default')}"></label><button class="button primary" data-feature="ml-load">Refresh labs</button><button class="button" data-feature="ml-models">Refresh models</button><button class="button" data-feature="ml-deployments">Refresh deployments</button></div><div class="grid two"><form class="panel" data-feature-form="ml-create"><h2>Create lab</h2><label>Lab ID<input class="field" name="id" value="churn" required></label><label>Name<input class="field" name="name" value="Churn baseline" required></label><label>Dataset asset<input class="field" name="asset_id" value="customers" required></label><label>Dataset version<input class="field" name="version" value="v1" required></label><label>Target<input class="field" name="target" value="target" required></label><label>Feature<input class="field" name="feature" value="x" required></label><button class="button primary">Create lab</button></form><div id="ml-labs" class="loading">Loading labs…</div></div><form class="panel" data-feature-form="ml-quality-suite"><h2>Quality gate suite</h2><label>Lab ID<input class="field" name="lab_id" value="churn" required></label><label>Reusable versioned suite JSON<textarea class="field" name="suite" required>{"schema":"ronin.ml-quality-suite/v1","id":"baseline-quality","version":1,"expectations":[{"id":"feature-x-numeric","column":"x","rule":"numeric","severity":"failure","value":null}]}</textarea></label><div class="toolbar"><button class="button" type="button" data-feature="ml-quality-suite-list">Load saved suites</button><select class="field" name="saved_suite" aria-label="Saved quality suite"><option value="">Choose a saved suite</option></select><button class="button primary" type="submit">Save and use for runs</button></div></form><form class="panel" data-feature-form="ml-compare"><h2>Compare trials</h2><label>Lab ID<input class="field" name="lab_id" value="churn" required></label><label>Metric<input class="field" name="metric" value="accuracy" required></label><label>Tie-breakers JSON<textarea class="field" name="tie_breakers">[]</textarea></label><label>Trial JSON<textarea class="field" name="trials">[{"parameters":{"C":1},"metrics":{"accuracy":0.8}},{"parameters":{"C":2},"metrics":{"accuracy":0.9}}]</textarea></label><button class="button primary">Rank trials</button></form><div id="ml-output" class="panel feature-output"></div><div id="ml-models" class="panel feature-output"><h2>Registered models</h2><div class="loading">Loading models…</div></div><section id="ml-deployments" class="panel feature-output"><h2>Deployments</h2><form data-feature-form="ml-deployment-create" class="toolbar"><input class="field" name="deployment_id" placeholder="deployment-id" required><input class="field" name="model_id" placeholder="model-id" required><input class="field" name="version" placeholder="version" required><input class="field" name="endpoint" value="local" required><button class="button primary">Deploy pinned model</button></form><div id="ml-deployment-list" class="loading">Loading deployments…</div></section>`;
  root().querySelector('[data-feature-form="ml-compare"]').addEventListener('submit',async e=>{
    e.preventDefault();
    const form=e.currentTarget;
    const d=Object.fromEntries(new FormData(form));
    try{
      const tie_breakers=JSON.parse(form.querySelector('textarea[name="tie_breakers"]')?.value||'[]');
      const result=await post(`/v1/ml-studio/labs/${encodeURIComponent(d.lab_id)}/compare?workspace_id=${encodeURIComponent(mlWorkspace())}`,{spec:{mode:'single',metric:d.metric,direction:'maximize',tie_breakers},trials:JSON.parse(d.trials)});
      mlCompareExport=result;
      document.querySelector('#ml-output').innerHTML=`<h2>Trial ranking</h2><div class="toolbar"><label>Filter trials<input class="field" data-ml-compare-filter type="search" placeholder="ID, parameter, or metric"></label><button class="button" data-feature="ml-compare-export-json">Export JSON</button><button class="button" data-feature="ml-compare-export-csv">Export CSV</button></div><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Trial</th><th>Parameters</th><th>Metrics</th></tr></thead><tbody>${(result.items||[]).map((trial,index)=>`<tr><td>${index+1}</td><td>${esc(trial.trial_id)}</td><td><code>${esc(json(trial.parameters))}</code></td><td><code>${esc(json(trial.metrics))}</code></td></tr>`).join('')}</tbody></table></div><details open><summary>Tie-breakers</summary><pre class="code">${esc(json(result.tie_breakers || []))}</pre></details>`;
    }catch(err){document.querySelector('#ml-output').innerHTML=error(err.message)}
  });
  ensureMLScoreForm();await loadMLLabs();await loadMLModels();await loadMLDeployments()
}
function mlWorkspace(){return document.querySelector('#ml-workspace')?.value.trim()||'default'}
function mlQualitySuiteKey(workspace,lab){return `ml-quality-suite:${encodeURIComponent(workspace)}:${encodeURIComponent(lab)}`}
async function loadMLModels(){const out=document.querySelector('#ml-models');if(!out)return;try{const data=await get(`/v1/ml-studio/models?workspace_id=${encodeURIComponent(mlWorkspace())}`);const rows=data.items||[];out.innerHTML=`<h2>Registered models</h2>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Model</th><th>Version</th><th>Stage</th><th>Action</th></tr></thead><tbody>${rows.map(m=>`<tr><td>${esc(m.model_id)}</td><td>${esc(m.version)}</td><td>${esc(m.stage)}</td><td><button class="button" data-feature="ml-card" data-model="${esc(m.model_id)}" data-version="${esc(m.version)}">Model card</button> <button class="button" data-feature="ml-download" data-model="${esc(m.model_id)}" data-version="${esc(m.version)}">Download artifact</button>${m.stage==='candidate'?` <button class="button primary" data-feature="ml-promote" data-model="${esc(m.model_id)}" data-version="${esc(m.version)}">Promote</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No registered models.</div>'}`}catch(e){out.innerHTML=error(e.message)}}
async function loadMLDeployments(){const out=document.querySelector('#ml-deployment-list');if(!out)return;try{const data=await get(`/v1/ml-studio/deployments?workspace_id=${encodeURIComponent(mlWorkspace())}`);const rows=data.items||[];out.className='';out.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Deployment</th><th>Model</th><th>Status</th><th>Digest</th><th>Actions</th></tr></thead><tbody>${rows.map(d=>`<tr><td><code>${esc(d.deployment_id)}</code></td><td>${esc(d.model_id)}@${esc(d.version)}</td><td>${esc(d.status)} / ${esc(d.readiness)}</td><td><code>${esc(d.artifact_digest.slice(0,16))}…</code></td><td><button class="button" data-feature="ml-deployment-health" data-deployment="${esc(d.deployment_id)}">Health</button> <button class="button" data-feature="ml-deployment-predict" data-deployment="${esc(d.deployment_id)}">Predict</button>${d.status!=='rolled_back'?` <button class="button danger" data-feature="ml-deployment-rollback" data-deployment="${esc(d.deployment_id)}">Rollback</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No model deployments.</div>'}catch(e){out.innerHTML=error(e.message)}}
async function mlDeploymentHealth(id){try{const data=await get(`/v1/ml-studio/deployments/${encodeURIComponent(id)}/health?workspace_id=${encodeURIComponent(mlWorkspace())}`);document.querySelector('#ml-output').innerHTML=`<h2>Deployment health</h2><pre class="code">${esc(json(data))}</pre>`}catch(e){document.querySelector('#ml-output').innerHTML=error(e.message)}}
async function mlRollbackDeployment(id){if(!await confirmImpact(`Rollback deployment ${id}?`))return;try{await post(`/v1/ml-studio/deployments/${encodeURIComponent(id)}/rollback?workspace_id=${encodeURIComponent(mlWorkspace())}`,{});await loadMLDeployments()}catch(e){document.querySelector('#ml-output').innerHTML=error(e.message)}}
async function mlPredictDeployment(id){const raw=window.prompt('Rows JSON','[{"x":1}]');if(raw===null)return;try{const rows=JSON.parse(raw);if(!Array.isArray(rows))throw new Error('Rows must be a JSON array');const data=await post(`/v1/ml-studio/deployments/${encodeURIComponent(id)}/predict?workspace_id=${encodeURIComponent(mlWorkspace())}`,{rows});document.querySelector('#ml-output').innerHTML=`<h2>Deployment predictions</h2><pre class="code">${esc(json(data))}</pre>`;await loadMLDeployments()}catch(e){document.querySelector('#ml-output').innerHTML=error(e.message)}}
async function mlCard(model,version){try{const data=await get(`/v1/ml-studio/models/${encodeURIComponent(model)}/${encodeURIComponent(version)}/card?workspace_id=${encodeURIComponent(mlWorkspace())}`);document.querySelector('#ml-output').innerHTML=`<h2>Model card</h2><pre class="code">${esc(json(data))}</pre>`}catch(e){document.querySelector('#ml-output').innerHTML=error(e.message)}}
async function mlDownloadArtifact(model,version,button){const workspace=encodeURIComponent(mlWorkspace());const base=`/v1/ml-studio/models/${encodeURIComponent(model)}/${encodeURIComponent(version)}/artifact?workspace_id=${workspace}`;const previous=button.textContent;button.disabled=true;button.textContent='Downloading…';const chunks=[];let offset=0;let metadata=null;try{for(;;){const part=await get(`${base}&offset=${offset}&length=524288`);if(part.model_id!==model||part.version!==version||!Number.isSafeInteger(part.size_bytes)||part.size_bytes<1||part.size_bytes>67108864||!Number.isSafeInteger(part.offset)||part.offset!==offset||typeof part.digest!=='string'||!/^[a-f0-9]{64}$/.test(part.digest)||typeof part.media_type!=='string'||typeof part.data_base64!=='string')throw new Error('Artifact response metadata is invalid');if(metadata&&(part.digest!==metadata.digest||part.size_bytes!==metadata.size_bytes||part.media_type!==metadata.media_type))throw new Error('Artifact changed while downloading');metadata??=part;const raw=atob(part.data_base64);if(!raw.length||raw.length>524288||offset+raw.length>part.size_bytes)throw new Error('Artifact chunk size is invalid');const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i+=1)bytes[i]=raw.charCodeAt(i);chunks.push(bytes);offset+=bytes.length;if(part.complete){if(offset!==part.size_bytes||part.next_offset!==null)throw new Error('Artifact download ended at an invalid offset');break}if(part.next_offset!==offset||offset>=part.size_bytes)throw new Error('Artifact chunk sequence is invalid')}const blob=new Blob(chunks,{type:metadata.media_type});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`${model}-${version}.artifact`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#ml-output').innerHTML=`<p role="status">Downloaded ${esc(model)}@${esc(version)} (${offset} bytes, SHA-256 ${esc(metadata.digest)}).</p>`}catch(e){document.querySelector('#ml-output').innerHTML=error(e.message)}finally{button.disabled=false;button.textContent=previous}}
function ensureMLScoreForm(){if(document.querySelector('[data-feature-form="ml-score"]'))return;document.querySelector('#ml-output')?.insertAdjacentHTML('beforebegin','<form class="panel" data-feature-form="ml-score"><h2>Batch score</h2><label>Model ID<input class="field" name="model_id" required></label><label>Version<input class="field" name="version" required></label><label>Batch ID<input class="field" name="batch_id" value="studio-batch-1" required></label><label>Artifact Base64 (optional)<textarea class="field" name="artifact_base64"></textarea></label><label>Rows JSON<textarea class="field" name="rows">[{"x":1}]</textarea></label><button class="button primary">Score rows</button></form>')}
async function mlPromote(model,version){const reason=window.prompt('Promotion reason');if(!reason?.trim())return;try{await post(`/v1/ml-studio/models/${encodeURIComponent(model)}/${encodeURIComponent(version)}/promote?workspace_id=${encodeURIComponent(mlWorkspace())}`,{reason:reason.trim()});await loadMLModels()}catch(e){document.querySelector('#ml-output').innerHTML=error(e.message)}}
function mlAlgorithms(task){if(task==='classification')return['logistic_regression','decision_tree_classifier','random_forest_classifier','gradient_boosting_classifier'];if(task==='regression')return['linear_regression','decision_tree_regressor','random_forest_regressor','gradient_boosting_regressor'];return[]}
function mlDrift(id){const row=document.querySelector(`[data-feature="ml-drift"][data-lab="${CSS.escape(id)}"]`)?.closest('tr');if(!row)return;const features=JSON.parse(row.dataset.mlFeatures||'[]').filter(feature=>feature.role==='numeric').map(feature=>feature.column);if(!features.length){document.querySelector('#ml-output').innerHTML=error('Drift reports require at least one feature with numeric role.');return}const policy={schema:'ronin.ml-drift-policy/v1',id:`${id}-numeric-drift`,version:1,thresholds:features.map(feature=>({feature,mean_delta:0,variance_delta:0}))};document.querySelector('#ml-output').innerHTML=`<section class="panel"><h2>Numeric drift report</h2><p>Enter baseline and current row windows for Lab <code>${esc(id)}</code>. Thresholds compare absolute mean and population-variance deltas. Save the versioned policy JSON for reuse.</p><form data-feature-form="ml-drift" data-lab="${esc(id)}"><label>Baseline rows JSON<textarea class="field" name="baseline_rows" required>[]</textarea></label><label>Current rows JSON<textarea class="field" name="current_rows" required>[]</textarea></label><label>Versioned drift policy JSON<textarea class="field" name="policy" required>${esc(JSON.stringify(policy,null,2))}</textarea></label><div class="toolbar"><button class="button" type="button" data-feature="ml-drift-policies-list" data-lab="${esc(id)}">Load saved policies</button><select class="field" name="saved_policy" aria-label="Saved drift policy"><option value="">Choose a saved policy</option></select><button class="button" type="button" data-feature="ml-drift-policy-save" data-lab="${esc(id)}">Save policy version</button><button class="button primary" type="submit">Generate drift report</button></div></form></section>`}
async function loadMLLabs() {
  const out = document.querySelector('#ml-labs');
  if (!out) return;
  out.className = 'loading';
  out.textContent = 'Loading labs…';
  try {
    const data = await get(`/v1/ml-studio/labs?workspace_id=${encodeURIComponent(mlWorkspace())}`);
    let backends = [];
    let backendStatusError = false;
    try {
      const backendData = await get('/v1/ml-studio/backends');
      backends = backendData.items || [];
    } catch (_) {
      backendStatusError = true;
    }
    const backendById = new Map(backends.map(backend => [backend.id, backend]));
    const rows = data.items || [];
    out.className = '';
    out.innerHTML = rows.length ? `<div class="table-wrap"><table><thead><tr><th>Lab</th><th>Task</th><th>Backend</th><th>Algorithm</th><th>Preprocessor</th><th>Actions</th></tr></thead><tbody>${rows.map(lab => {
      const algorithms = mlAlgorithms(lab.task);
      const categorical = (lab.features || []).some(feature => feature.role === 'categorical');
      const backend = backendById.get(lab.backend_id);
      const available = backend?.status === 'available';
      const disabled = available ? '' : ' disabled';
      const unavailableMessage = backendStatusError
        ? 'Backend status could not be loaded. Refresh the Labs list before training.'
        : backend?.reason || 'Backend is not available or does not advertise its status.';
      return `<tr data-ml-features="${esc(JSON.stringify(lab.features || []))}" data-ml-target="${esc(lab.target || '')}" data-ml-task="${esc(lab.task)}"><td><strong>${esc(lab.name)}</strong><br><code>${esc(lab.id)}</code></td><td>${esc(lab.task)}</td><td>${esc(lab.backend_id)}${!available ? `<small class="muted" role="status">Training unavailable. ${esc(unavailableMessage)}</small>` : ''}</td><td>${algorithms.length ? `<select class="field" multiple size="4" aria-label="Candidate algorithms for ${esc(lab.name)}" data-ml-algorithm="${esc(lab.id)}"${disabled}>${algorithms.map((algorithm, index) => `<option value="${esc(algorithm)}"${index === 0 ? ' selected' : ''}>${esc(algorithm)}</option>`).join('')}</select><small class="muted">Select algorithms and preprocessors to compare combinations; maximum 8 candidates.</small>` : `<select class="field" multiple size="3" aria-label="Candidate cluster counts for ${esc(lab.name)}" data-ml-cluster-count="${esc(lab.id)}"${disabled}><option value="2" selected>2 clusters</option><option value="3" selected>3 clusters</option><option value="4">4 clusters</option></select><small class="muted">Select at least two cluster counts.</small>`}</td><td>${algorithms.length ? `<select class="field" multiple size="3" aria-label="Candidate preprocessors for ${esc(lab.name)}" data-ml-preprocessor="${esc(lab.id)}"${disabled}>${categorical ? '<option value="one_hot" selected>One hot encoding</option><option value="one_hot_median_impute">One hot + median imputation</option>' : '<option value="identity" selected>Identity</option><option value="standard_scale">Standard scale</option><option value="median_impute">Median imputation</option>'}</select><small class="muted">Select preprocessors; combined grid maximum is 8 candidates.</small>` : 'Not applicable'}</td><td><label><input type="checkbox" data-ml-register="${esc(lab.id)}"${disabled}> Register selected model</label><input class="field" data-ml-register-version="${esc(lab.id)}" aria-label="Registered model version for ${esc(lab.name)}" placeholder="Version (optional)"${disabled}><button class="button" data-feature="ml-compile" data-lab="${esc(lab.id)}">Compile</button><button class="button" data-feature="ml-drift" data-lab="${esc(lab.id)}">Drift report</button><button class="button primary" data-feature="ml-run" data-lab="${esc(lab.id)}"${disabled}>Run sample</button></td></tr>`;
    }).join('')}</tbody></table></div>` : '<div class="empty">No labs are registered.</div>';
  } catch (e) {
    out.className = '';
    out.innerHTML = error(e.message);
  }
}
async function mlCompile(id){try{const data=await post(`/v1/ml-studio/labs/${encodeURIComponent(id)}/compile?workspace_id=${encodeURIComponent(mlWorkspace())}`,{});document.querySelector('#ml-output').innerHTML=`<h2>Compiled pipeline</h2><pre class="code">${esc(json(data))}</pre>`}catch(e){document.querySelector('#ml-output').innerHTML=error(e.message)}}
async function mlRun(id){try{const row=document.querySelector(`[data-ml-algorithm="${CSS.escape(id)}"],[data-ml-cluster-count="${CSS.escape(id)}"],[data-feature="ml-run"][data-lab="${CSS.escape(id)}"]`)?.closest('tr');const features=JSON.parse(row?.dataset.mlFeatures||'[]');const target=row?.dataset.mlTarget??'target';const task=row?.dataset.mlTask||'classification';const rows=Array.from({length:20},(_,i)=>{const sample={};for(const feature of features)sample[feature.column]=feature.role==='categorical'?`category-${i%2}`:i+1;if(target)sample[target]=task==='classification'?i%2:i+1;if(!features.length)sample.x=i+1;return sample});const body={run_id:`ui-${id}-${Date.now()}`,rows};const suite=sessionStorage.getItem(mlQualitySuiteKey(mlWorkspace(),id));if(suite)body.quality_suite=JSON.parse(suite);const algorithmSelect=document.querySelector(`[data-ml-algorithm="${CSS.escape(id)}"]`);const selectedAlgorithms=algorithmSelect?[...algorithmSelect.selectedOptions].map(option=>option.value):[];if(selectedAlgorithms.length>1)body.candidate_algorithms=selectedAlgorithms;else if(selectedAlgorithms.length===1)body.algorithm=selectedAlgorithms[0];const clusterSelect=document.querySelector(`[data-ml-cluster-count="${CSS.escape(id)}"]`);if(clusterSelect){const counts=[...clusterSelect.selectedOptions].map(option=>Number(option.value));if(counts.length<2)throw new Error('Select at least two cluster counts');body.candidate_cluster_counts=counts}const preprocessorSelect=document.querySelector(`[data-ml-preprocessor="${CSS.escape(id)}"]`);const selectedPreprocessors=preprocessorSelect?[...preprocessorSelect.selectedOptions].map(option=>option.value):[];if(selectedPreprocessors.length>1)body.candidate_preprocessors=selectedPreprocessors;else if(selectedPreprocessors.length===1)body.preprocessor=selectedPreprocessors[0];const registerToggle=row?.querySelector(`[data-ml-register="${CSS.escape(id)}"]`);if(registerToggle?.checked){const version=row.querySelector(`[data-ml-register-version="${CSS.escape(id)}"]`)?.value.trim()||`candidate-${Date.now()}`;body.register={model_id:id,version}}const candidateCount=(body.candidate_algorithms?.length||1)*(body.candidate_preprocessors?.length||1);if(candidateCount>8)throw new Error('A candidate grid can contain at most 8 combinations');const data=await post(`/v1/ml-studio/labs/${encodeURIComponent(id)}/executions?workspace_id=${encodeURIComponent(mlWorkspace())}`,body);document.querySelector('#ml-output').innerHTML=`<h2>Execution submitted</h2><pre id="ml-execution" class="code">${esc(json(data))}</pre>`;pollML(data.run_id,id)}catch(e){document.querySelector('#ml-output').innerHTML=error(e.message)}}
async function pollML(runId,labId){for(let i=0;i<60;i+=1){await new Promise(resolve=>setTimeout(resolve,250));try{const data=await get(`/v1/ml-studio/executions/${encodeURIComponent(runId)}?workspace_id=${encodeURIComponent(mlWorkspace())}`);const out=document.querySelector('#ml-execution');if(out)out.textContent=json(data);if(data.state==='succeeded'){if(data.result?.registered_model){const model=data.result.registered_model;if(out)out.insertAdjacentHTML('afterend',`<p role="status">Registered candidate ${esc(model.model_id)}@${esc(model.version)}.</p>`);await loadMLModels()}else if(out&&!document.querySelector('#ml-register-execution'))out.insertAdjacentHTML('afterend',`<form id="ml-register-execution" class="panel" data-run-id="${esc(runId)}"><h3>Register this run as a candidate model</h3><label>Model ID<input class="field" name="model_id" value="${esc(labId)}" required></label><label>Version<input class="field" name="version" value="${esc(runId)}" required></label><button class="button primary" type="submit">Register candidate</button></form>`);return}if(data.state==='failed'){if(out&&!document.querySelector('#ml-retry-execution'))out.insertAdjacentHTML('afterend',`<form id="ml-retry-execution" class="panel" data-run-id="${esc(runId)}" data-lab-id="${esc(labId)}"><h3>Retry from a pipeline stage</h3><label>Retry run ID<input class="field" name="retry_run_id" value="${esc(`${runId}-retry-${Date.now()}`)}" maxlength="256" required></label><label>Start stage<select class="field" name="from_stage">${(Array.isArray(data.pipeline_stages)&&data.pipeline_stages.length?data.pipeline_stages:[{id:"profile",kind:"profile"},{id:"quality_gate",kind:"quality_gate"},{id:"prepare",kind:"prepare"},{id:"train",kind:"train"},{id:"evaluate",kind:"evaluate"},{id:"select",kind:"select"},{id:"register",kind:"register"}]).map(stage=>`<option value="${esc(stage.id)}">${esc(stage.kind)} — ${esc(stage.id)}</option>`).join("")}</select></label><button class="button primary" type="submit">Retry execution</button></form>`);return}if(data.state==='cancelled')return}catch(e){return}}}
document.addEventListener('submit',async e=>{if(e.target.id!=='ml-retry-execution')return;e.preventDefault();const form=e.target;const values=Object.fromEntries(new FormData(form));try{const retry=await post(`/v1/ml-studio/executions/${encodeURIComponent(form.dataset.runId)}/retry?workspace_id=${encodeURIComponent(mlWorkspace())}`,{run_id:String(values.retry_run_id).trim(),from_stage:String(values.from_stage)});form.remove();document.querySelector('#ml-output').innerHTML=`<h2>Selective retry submitted</h2><pre id="ml-execution" class="code">${esc(json(retry))}</pre>`;pollML(retry.run_id,form.dataset.labId)}catch(err){form.insertAdjacentHTML('beforeend',error(err.message))}});
document.addEventListener('submit',async e=>{if(e.target.id!=='ml-register-execution')return;e.preventDefault();const form=e.target;const values=Object.fromEntries(new FormData(form));try{const model=await post(`/v1/ml-studio/executions/${encodeURIComponent(form.dataset.runId)}/register?workspace_id=${encodeURIComponent(mlWorkspace())}`,{model_id:String(values.model_id).trim(),version:String(values.version).trim()});form.innerHTML=`<p role="status">Registered candidate ${esc(model.model_id)}@${esc(model.version)}</p><button class="button primary" type="button" data-feature="ml-promote" data-model="${esc(model.model_id)}" data-version="${esc(model.version)}">Promote candidate</button>`;await loadMLModels()}catch(err){form.insertAdjacentHTML('beforeend',error(err.message))}});
async function renderFeature(){if(current()==='mlstudio'){await machineLearningStudio();return}if(current()==='environments'){await environments();return}if(current()==='workflows'){await workflows();return}if(current()==='workspaces'){await workspaces();workspaceControls();return}if(current()==='runs'){setTimeout(jobSubmitPanel,250);return}}
document.addEventListener('input',e=>{if(!e.target.matches('[data-feature-form="ml-quality-suite"] [name="lab_id"]'))return;const select=e.target.form.elements.namedItem('saved_suite');if(select)select.innerHTML='<option value="">Choose a saved suite</option>'});
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-feature="ml-quality-suite-list"]');if(!b)return;const f=b.closest('form');const lab=f?.elements.namedItem('lab_id')?.value.trim();if(!lab)return;try{const data=await get(`/v1/ml-studio/labs/${encodeURIComponent(lab)}/quality-suites?workspace_id=${encodeURIComponent(mlWorkspace())}`);const select=f.elements.namedItem('saved_suite');select.innerHTML='<option value="">Choose a saved suite</option>'+data.items.map((x,i)=>`<option value="${i}">${esc(x.id)}@${x.version}</option>`).join('');select.onchange=()=>{if(select.value!==''){const suite=data.items[Number(select.value)];const payload=JSON.stringify(suite);f.elements.namedItem('suite').value=payload;sessionStorage.setItem(mlQualitySuiteKey(mlWorkspace(),lab),payload)}};document.querySelector('#ml-output').innerHTML=`<p role="status">Loaded ${data.items.length} saved quality suite versions.</p>`}catch(err){document.querySelector('#ml-output').innerHTML=error(err.message)}});
  document.addEventListener('click',async e=>{const b=e.target.closest('[data-feature="ml-drift-policies-list"],[data-feature="ml-drift-policy-save"]');if(!b)return;const lab=b.dataset.lab;const form=document.querySelector(`[data-feature-form="ml-drift"][data-lab="${CSS.escape(lab)}"]`);if(!form)return;const select=form.elements.namedItem('saved_policy');try{if(b.dataset.feature==='ml-drift-policies-list'){const data=await get(`/v1/ml-studio/labs/${encodeURIComponent(lab)}/drift-policies?workspace_id=${encodeURIComponent(mlWorkspace())}`);select.innerHTML='<option value="">Choose a saved policy</option>'+data.items.map((x,i)=>`<option value="${i}">${esc(x.id)}@${x.version}</option>`).join('');select.onchange=()=>{if(select.value!==''){const policy=data.items[Number(select.value)];form.elements.namedItem('policy').value=JSON.stringify(policy,null,2)}};document.querySelector('#ml-output').insertAdjacentHTML('afterbegin',`<p role="status">Loaded ${data.items.length} saved drift policies.</p>`)}else{const policy=JSON.parse(form.elements.namedItem('policy').value);await post(`/v1/ml-studio/labs/${encodeURIComponent(lab)}/drift-policies?workspace_id=${encodeURIComponent(mlWorkspace())}`,policy);document.querySelector('#ml-output').insertAdjacentHTML('afterbegin',`<p role="status">Saved drift policy <code>${esc(policy.id)}@${policy.version}</code>.</p>`)}}catch(err){document.querySelector('#ml-output').insertAdjacentHTML('afterbegin',error(err.message))}});
  document.addEventListener('click',e=>{const el=e.target.closest('[data-feature]');if(!el)return;if(el.dataset.feature==='load-workflows')loadWorkflows();if(el.dataset.feature==='run-workflow')runWorkflow(el.dataset.workflow);if(el.dataset.feature==='load-workflow-run')showWorkflowRun(document.querySelector('#workflow-run-id')?.value.trim());if(el.dataset.feature==='cancel-workflow-run')cancelWorkflowRun(el.dataset.run);if(el.dataset.feature==='load-workspaces')loadWorkspaces();if(el.dataset.feature==='load-projects')loadProjects();if(el.dataset.feature==='select-workspace'){document.querySelector('#workspace-id').value=el.dataset.workspace;loadProjects()}if(el.dataset.feature==='inspect-workspace')inspectWorkspace(el.dataset.workspace);if(el.dataset.feature==='archive-workspace')archiveWorkspace(el.dataset.workspace);if(el.dataset.feature==='inspect-project')inspectProject(el.dataset.project);if(el.dataset.feature==='delete-project')deleteProject(el.dataset.project)});
document.addEventListener('submit',async e=>{if(e.target.matches('[data-feature-form="job-submit"]')){e.preventDefault();submitJob(e.target)}else if(e.target.matches('[data-feature-form="project-create"]')){e.preventDefault();submitProject(e.target)}else if(e.target.matches('[data-feature-form="workspace-update"]')){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await patch(`/v1/workspaces/${encodeURIComponent(d.id)}`,{name:d.name,description:d.description||null});await loadWorkspaces()}catch(err){e.target.insertAdjacentHTML('afterend',error(err.message))}}else if(e.target.matches('[data-feature-form="project-replace"]')){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const workspace=sessionStorage.getItem('ronin.workspace')||'default';try{await put(`/v1/workspaces/${encodeURIComponent(workspace)}/projects/${encodeURIComponent(d.project_id)}`,{id:d.project_id,name:d.name});await loadProjects()}catch(err){e.target.insertAdjacentHTML('afterend',error(err.message))}}else if(e.target.matches('[data-feature-form="ml-quality-suite"]')){e.preventDefault();try{const suite=JSON.parse(e.target.elements.namedItem('suite').value);if(!suite.id||!Number.isInteger(suite.version)||!Array.isArray(suite.expectations)||!suite.expectations.length)throw new Error('Quality suite requires an ID, positive version, and expectations');if(suite.version<1)throw new Error('Quality suite version must be positive');const lab=e.target.elements.namedItem('lab_id').value.trim();await post(`/v1/ml-studio/labs/${encodeURIComponent(lab)}/quality-suites?workspace_id=${encodeURIComponent(mlWorkspace())}`,suite);sessionStorage.setItem(mlQualitySuiteKey(mlWorkspace(),lab),JSON.stringify(suite));document.querySelector('#ml-output').innerHTML=`<p role="status">Saved quality suite <code>${esc(suite.id)}@${suite.version}</code>; it will run before training for this Lab.</p>`}catch(err){document.querySelector('#ml-output').innerHTML=error(err.message)}}});
window.addEventListener('hashchange',()=>setTimeout(()=>{replaceIcons();renderFeature()},0));
const railObserver=document.querySelector('#rail');if(railObserver)new MutationObserver(()=>{if(!railObserver.querySelector('.nav-icon svg'))replaceIcons()}).observe(railObserver,{childList:true});setTimeout(()=>{replaceIcons();renderFeature()},0);
document.addEventListener('click',e=>{const el=e.target.closest('[data-feature]');if(!el)return;if(el.dataset.feature==='ml-load')loadMLLabs();if(el.dataset.feature==='ml-models')loadMLModels();if(el.dataset.feature==='ml-deployments')loadMLDeployments();if(el.dataset.feature==='ml-deployment-health')mlDeploymentHealth(el.dataset.deployment);if(el.dataset.feature==='ml-deployment-predict')mlPredictDeployment(el.dataset.deployment);if(el.dataset.feature==='ml-deployment-rollback')mlRollbackDeployment(el.dataset.deployment);if(el.dataset.feature==='ml-card')mlCard(el.dataset.model,el.dataset.version);if(el.dataset.feature==='ml-download')mlDownloadArtifact(el.dataset.model,el.dataset.version,el);if(el.dataset.feature==='ml-promote')mlPromote(el.dataset.model,el.dataset.version);if(el.dataset.feature==='ml-compile')mlCompile(el.dataset.lab);if(el.dataset.feature==='ml-drift')mlDrift(el.dataset.lab);if(el.dataset.feature==='ml-run')mlRun(el.dataset.lab);if(el.dataset.feature==='ml-compare-export-json')exportMLCompare('json');if(el.dataset.feature==='ml-compare-export-csv')exportMLCompare('csv')});
document.addEventListener('input',e=>{if(!e.target.matches('[data-ml-compare-filter]'))return;const query=e.target.value.trim().toLowerCase();for(const row of document.querySelectorAll('#ml-output tbody tr'))row.hidden=query!==''&&!row.textContent.toLowerCase().includes(query)});
document.addEventListener('submit',async e=>{if(!e.target.matches('[data-feature-form="ml-create"]'))return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target));const body={schema:'ronin.ml-lab/v1',id:d.id,name:d.name,project_id:'default',dataset:{asset_id:d.asset_id,version:d.version},target:d.target,task:'classification',features:[{column:d.feature,role:'numeric'}],backend_id:'local.sklearn',seed:17,test_fraction:0.2};try{await post(`/v1/ml-studio/labs?workspace_id=${encodeURIComponent(mlWorkspace())}`,body);e.target.reset();await loadMLLabs()}catch(err){e.target.insertAdjacentHTML('afterend',error(err.message))}});
document.addEventListener('submit',async e=>{if(!e.target.matches('[data-feature-form="ml-deployment-create"]'))return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await post(`/v1/ml-studio/deployments?workspace_id=${encodeURIComponent(mlWorkspace())}`,{deployment_id:d.deployment_id,model_id:d.model_id,version:d.version,endpoint:d.endpoint});e.target.reset();await loadMLDeployments()}catch(err){e.target.insertAdjacentHTML('afterend',error(err.message))}});
document.addEventListener('submit',async e=>{if(!e.target.matches('[data-feature-form="ml-drift"]'))return;e.preventDefault();const form=e.target;const read=name=>form.elements.namedItem(name)?.value||'';try{const body={baseline_rows:JSON.parse(read('baseline_rows')),current_rows:JSON.parse(read('current_rows')),policy:JSON.parse(read('policy'))};const result=await post(`/v1/ml-studio/labs/${encodeURIComponent(form.dataset.lab)}/drift?workspace_id=${encodeURIComponent(mlWorkspace())}`,body);document.querySelector('#ml-output').innerHTML=`<h2>Drift report · ${esc(result.assessment.status)}</h2><pre class="code">${esc(json(result))}</pre>`}catch(err){document.querySelector('#ml-output').innerHTML=error(err.message)}});
document.addEventListener('submit',async e=>{if(!e.target.matches('[data-feature-form="ml-score"]'))return;e.preventDefault();const form=e.target;const value=name=>form.elements.namedItem(name)?.value?.trim()||'';try{const model=value('model_id');const version=value('version');const batch=value('batch_id');const rows=value('rows');if(!model||!version||!batch)throw new Error('Model, version and batch ID are required');const body={batch_id:batch,rows:JSON.parse(rows)};const artifact=value('artifact_base64');if(artifact)body.artifact_base64=artifact;const result=await post(`/v1/ml-studio/models/${encodeURIComponent(model)}/${encodeURIComponent(version)}/batch-predict?workspace_id=${encodeURIComponent(mlWorkspace())}`,body);document.querySelector('#ml-output').innerHTML=`<h2>Predictions</h2><pre class="code">${esc(json(result))}</pre>`}catch(err){document.querySelector('#ml-output').innerHTML=error(err.message)}});
window.addEventListener('hashchange',()=>{if(current()==='mlstudio')setTimeout(ensureMLScoreForm,300)});setTimeout(()=>{if(current()==='mlstudio')ensureMLScoreForm()},300);
setInterval(()=>{if(current()==='mlstudio')ensureMLScoreForm()},100);
export {machineLearningStudio};
async function workflows(){root().innerHTML=`${page('Workflows','SCHEDULER')}<div class="toolbar"><label>Workspace<input class="field" id="workflow-workspace" value="${esc(sessionStorage.getItem('ronin.workspace')||'default')}" required></label><button class="button primary" data-feature="load-workflows">Refresh workflows</button></div><div id="workflow-result" class="loading">Loading workflows…</div><section class="panel"><h2>Schedule authoring</h2><form id="schedule-form" class="toolbar"><input class="field" name="id" placeholder="daily-sales" required><input class="field" name="workflow_id" placeholder="workflow-id" required><input class="field" name="cron" value="0 * * * *" required><input class="field" name="timezone" value="UTC" required><label><input type="checkbox" name="enabled" checked> enabled</label><button class="button primary">Save schedule</button></form><pre id="schedule-result" class="code" aria-live="polite">No schedule change yet.</pre></section><section class="panel"><h2>Schedules</h2><div id="schedule-result-list" class="loading">Loading schedules…</div></section><div class="panel"><label>Workflow run ID<input class="field" id="workflow-run-id" placeholder="run id"><button class="button" data-feature="load-workflow-run">Inspect run</button></label><div id="workflow-run-result" class="empty">No workflow run selected.</div></div>`;sessionStorage.setItem('ronin.workspace',document.querySelector('#workflow-workspace').value);await loadWorkflows();await loadSchedules()}
async function loadSchedules(){const workspace=document.querySelector('#workflow-workspace')?.value.trim()||sessionStorage.getItem('ronin.workspace')||'default';const out=document.querySelector('#schedule-result-list');if(!out)return;try{const data=await get(`/v1/workspaces/${encodeURIComponent(workspace)}/schedules`);const rows=data.items||[];out.className='';out.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Schedule</th><th>Workflow</th><th>Cron</th><th>Timezone</th><th>Enabled</th></tr></thead><tbody>${rows.map(s=>`<tr><td><code>${esc(s.id)}</code></td><td>${esc(s.workflow_id)}</td><td>${esc(s.cron)}</td><td>${esc(s.timezone)}</td><td>${s.enabled?'yes':'no'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No schedules are published for this workspace.</div>'}catch(err){out.className='';out.innerHTML=error(err.message)}}
document.addEventListener('submit',async event=>{if(event.target.id!=='schedule-form')return;event.preventDefault();const data=Object.fromEntries(new FormData(event.target));const workspace=document.querySelector('#workflow-workspace').value.trim()||'default';try{const result=await put(`/v1/workspaces/${encodeURIComponent(workspace)}/schedules/${encodeURIComponent(data.id)}`,{id:data.id,workflow_id:data.workflow_id,cron:data.cron,timezone:data.timezone,enabled:data.enabled==='on'});document.querySelector('#schedule-result').textContent=json(result);await loadSchedules()}catch(error){document.querySelector('#schedule-result').textContent=`Schedule save failed: ${error.message}`}});
function injectEventTriggerStudio(){if(!document.querySelector('#workflow-result')||document.querySelector('#event-trigger-form'))return;document.querySelector('#workflow-result').insertAdjacentHTML('afterend',`<section class="panel"><h2>Event trigger authoring</h2><form id="event-trigger-form" class="toolbar"><input class="field" name="id" placeholder="orders-arrived" required><input class="field" name="workflow_id" placeholder="workflow-id" required><input class="field" name="event_type" placeholder="orders.created" required><input class="field" name="source_ref" placeholder="source (optional)"><input class="field" name="subject_ref" placeholder="subject (optional)"><label><input type="checkbox" name="enabled" checked> enabled</label><button class="button primary">Save trigger</button></form><pre id="event-trigger-result" class="code" aria-live="polite">No event trigger change yet.</pre><div id="event-trigger-list" class="loading">Loading event triggers…</div></section>`);loadEventTriggers()}
async function loadEventTriggers(){const workspace=document.querySelector('#workflow-workspace')?.value.trim()||'default';const out=document.querySelector('#event-trigger-list');if(!out)return;try{const data=await get(`/v1/workspaces/${encodeURIComponent(workspace)}/event-triggers`);const rows=data.items||[];out.className='';out.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Workflow</th><th>Event</th><th>Source</th><th>Enabled</th></tr></thead><tbody>${rows.map(t=>`<tr><td><code>${esc(t.id)}</code></td><td>${esc(t.workflow_id)}</td><td>${esc(t.event_type)}</td><td>${esc(t.source_ref||'—')}</td><td>${t.enabled?'yes':'no'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No event triggers are published for this workspace.</div>'}catch(err){out.className='';out.innerHTML=error(err.message)}}
document.addEventListener('submit',async event=>{if(event.target.id!=='event-trigger-form')return;event.preventDefault();const data=Object.fromEntries(new FormData(event.target));const workspace=document.querySelector('#workflow-workspace').value.trim()||'default';try{const payload={id:data.id,workflow_id:data.workflow_id,event_type:data.event_type,source_ref:data.source_ref||null,subject_ref:data.subject_ref||null,enabled:data.enabled==='on'};const result=await put(`/v1/workspaces/${encodeURIComponent(workspace)}/event-triggers/${encodeURIComponent(data.id)}`,payload);document.querySelector('#event-trigger-result').textContent=json(result);await loadEventTriggers()}catch(error){document.querySelector('#event-trigger-result').textContent=`Event trigger save failed: ${error.message}`}});new MutationObserver(injectEventTriggerStudio).observe(document.body,{childList:true,subtree:true});setTimeout(injectEventTriggerStudio,0);
function injectBackfillStudio(){if(!document.querySelector('#workflow-result')||document.querySelector('#backfill-form'))return;document.querySelector('#workflow-result').insertAdjacentHTML('afterend',`<section class="panel"><h2>Backfill administration</h2><form id="backfill-form"><div class="grid two"><label>Backfill ID<input class="field" name="id" placeholder="backfill-1" required></label><label>Schedule ID<input class="field" name="schedule_id" required></label><label>Start (ISO 8601)<input class="field" name="start_at" value="2026-01-01T00:00:00Z" required></label><label>End (ISO 8601)<input class="field" name="end_at" value="2026-01-02T00:00:00Z" required></label></div><div class="toolbar"><button class="button primary" type="submit">Create backfill</button><button class="button danger" type="button" data-feature="cancel-backfill">Cancel by ID</button></div></form><pre id="backfill-result" class="code" aria-live="polite">No backfill operation yet.</pre></section>`)}
document.addEventListener('submit',async event=>{if(event.target.id!=='backfill-form')return;event.preventDefault();const data=Object.fromEntries(new FormData(event.target));const workspace=document.querySelector('#workflow-workspace').value.trim()||'default';try{const result=await post(`/v1/workspaces/${encodeURIComponent(workspace)}/backfills`,{id:data.id,schedule_id:data.schedule_id,start_at:data.start_at,end_at:data.end_at});document.querySelector('#backfill-result').textContent=json(result)}catch(error){document.querySelector('#backfill-result').textContent=`Backfill creation failed: ${error.message}`}});document.addEventListener('click',async event=>{const button=event.target.closest('[data-feature="cancel-backfill"]');if(!button)return;const id=window.prompt('Backfill ID to cancel');if(!id?.trim())return;const workspace=document.querySelector('#workflow-workspace').value.trim()||'default';try{const result=await post(`/v1/workspaces/${encodeURIComponent(workspace)}/backfills/${encodeURIComponent(id.trim())}/cancel`,{});document.querySelector('#backfill-result').textContent=json(result)}catch(error){document.querySelector('#backfill-result').textContent=`Backfill cancellation failed: ${error.message}`}});new MutationObserver(injectBackfillStudio).observe(document.body,{childList:true,subtree:true});setTimeout(injectBackfillStudio,0);
